window.DS_INDEX = [{"t":"Introduction","s":"Overview","d":"The visual foundations, components and page patterns behind micahhoang.com.","h":"index.html"},{"t":"Principles","s":"Foundations","d":"Five words that settle design decisions, and the voice the site writes in.","h":"foundations/principles.html"},{"t":"Interaction Principles","s":"Foundations","d":"Apple's fluid-interface and design principles from its WWDC talks, applied to this brand. Each rule is labeled as already true, for new work, or a deliberate departure.","h":"foundations/interaction.html"},{"t":"Colors","s":"Foundations","d":"Two surfaces, Cream and Forest Green, and the semantic roles that re-map between them.","h":"foundations/colors.html"},{"t":"Typography","s":"Foundations","d":"GT Standard for display and reading, GT Standard Mono for every label, and a scale with a huge top and a small bottom.","h":"foundations/typography.html"},{"t":"Layout","s":"Foundations","d":"Edge-to-edge content inside a 20px gutter, two- and three-column grids, rules instead of boxes, three breakpoints.","h":"foundations/layout.html"},{"t":"Motion","s":"Foundations","d":"Three curves, a short list of durations, and the two signature moves, the flip rail and the type reveal.","h":"foundations/motion.html"},{"t":"Gesture","s":"Foundations","d":"How things the visitor can grab should move. What /play already does, and the spring tokens for any new drag, swipe or sheet.","h":"foundations/gesture.html"},{"t":"Texture","s":"Foundations","d":"The umber film grain that sits over every page, and how to keep it out of the way.","h":"foundations/texture.html"},{"t":"Identity","s":"Foundations","d":"The name as wordmark, the ©2026 signature, and where each appears.","h":"foundations/identity.html"},{"t":"Mono Label","s":"Components","d":"The uppercase 13px mono line that carries every piece of metadata, navigation and UI text on the site.","h":"components/label.html"},{"t":"Text Link","s":"Components","d":"Mono links with the flip-rail hover, inline underlined links for running text, and comma-joined link lists.","h":"components/text-link.html"},{"t":"Action","s":"Components","d":"The brand's button. Mono text with a flip rail, or an outlined pill. There is no filled button.","h":"components/action.html"},{"t":"Tag","s":"Components","d":"Outlined mono pills that name a project's disciplines and double as filters.","h":"components/tag.html"},{"t":"Rule","s":"Components","d":"The 1px near-black line that does the work boxes and cards do elsewhere, with an optional draw-in.","h":"components/rule.html"},{"t":"Section Header","s":"Components","d":"A full-width rule followed by a Display M title. This is how every major section on the site starts.","h":"components/section-header.html"},{"t":"Navigation","s":"Components","d":"The four-zone mono bar on every page (name, role, location, links) that hides on scroll and stays clear of the grain.","h":"components/navigation.html"},{"t":"Footer","s":"Components","d":"A Forest Green block with oversized uppercase contact links and a mono base bar.","h":"components/footer.html"},{"t":"Hero","s":"Components","d":"The opening of a page. A huge name and descriptor on Home; a bold title continuing in Light Gray on case studies.","h":"components/hero.html"},{"t":"Media Frame","s":"Components","d":"An aspect-locked, square-cornered frame for images and video, with a poster-under-video stack and an optional 1px stroke.","h":"components/media-frame.html"},{"t":"Project Card","s":"Components","d":"The main way work appears on the site. A numbered mono title that flips on hover, a 16:9 media frame, and discipline tags.","h":"components/project-card.html"},{"t":"Project Grid","s":"Components","d":"The grid that holds project cards. Two columns for Selected work, three for Other projects and the index grid.","h":"components/project-grid.html"},{"t":"Index List","s":"Components","d":"The complete archive as a ruled table. Year groups, uppercase titles, discipline and industry columns, with a hover wash and a flip.","h":"components/index-list.html"},{"t":"Filter Group","s":"Components","d":"Taxonomy columns of mono toggles (year, discipline, industry) that filter the Index in place.","h":"components/filter-group.html"},{"t":"View Toggle","s":"Components","d":"A mono \"GRID / LIST\" switch that changes how the Index renders, with an underline on the active view.","h":"components/view-toggle.html"},{"t":"Meta Grid","s":"Components","d":"The case-study fact sheet. \"/ LABEL\" mono headings over Body L values, in two columns.","h":"components/meta-grid.html"},{"t":"Lightbox","s":"Components","d":"A white full-screen viewer for case-study media, with thin near-black arrows and a quick zoom.","h":"components/lightbox.html"},{"t":"Testimonial","s":"Components","d":"A large quote with name and role, stepped with typed arrows. Used inside case studies.","h":"components/testimonial.html"},{"t":"Scroll to Top","s":"Components","d":"A mono text action at the end of long pages that glides back to the top in 900ms.","h":"components/scroll-to-top.html"},{"t":"Page Loader","s":"Components","d":"The first-visit boot curtain. Forest Green, a Cream progress bar, the name centered, then a lift.","h":"components/page-loader.html"},{"t":"Grain Overlay","s":"Components","d":"The page-level SVG film grain, fixed under the nav, multiplied at 10%, with an optional 16fps shimmer.","h":"components/grain-overlay.html"},{"t":"Home","s":"Patterns","d":"Name, descriptor, six selected projects, a short About, then the footer. The ten-second read.","h":"patterns/home.html"},{"t":"Case Study","s":"Patterns","d":"The template every project page follows. Two-tone title, full-bleed media, fact sheet, then titled chapters of media and short text.","h":"patterns/case-study.html"},{"t":"Index","s":"Patterns","d":"The complete archive. Filters across the top, a grid/list toggle, and a ruled year-by-year list.","h":"patterns/index-archive.html"}];
